mapper.update:
UPDATE tc_msg_send_log
   SET result          = #{l.result, typeHandler=org.apache.ibatis.type.EnumTypeHandler},
       kafka_partition = #{l.kafkaPartition},
       kafka_offset    = #{l.kafkaOffset},
       error_code      = #{l.errorCode},
       error_message   = #{l.errorMessage},
       sent_at         = #{l.sentAt, typeHandler=com.nori.tc.db.mybatis.common.typehandler.OffsetDateTimeTypeHandler}
 WHERE msg_key    = #{l.msgKey}
   AND attempt_no = #{l.attemptNo}

mapper.select:
SELECT 
  FROM tc_msg_send_log
 WHERE msg_key    = #{msgKey}
   AND attempt_no = #{attemptNo}

SELECT 
  FROM tc_msg_send_log
 WHERE msg_key = #{msgKey}
 ORDER BY attempt_no ASC, send_log_key ASC
 LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM tc_msg_send_log
 WHERE msg_key    = #{msgKey}
   AND attempt_no = #{attemptNo}
